"""Nederlands — beginnersniveau (200 vragen)."""

T = {
"prophets_251": ("Hoe heet de Profeet van de islam?", ["Muhammad ﷺ", "Ibrahim", "Musa", "Isa"], "De Profeet van de islam is Muhammad ﷺ, zoon van 'Abdullah."),
"prophets_252": ("Van welke profeet zijn Isma'il en Ishaq de zonen?", ["Ibrahim", "Musa", "Nuh", "Dawud"], "«Alle lof zij Allah, die mij ondanks mijn ouderdom Isma'il en Ishaq heeft geschonken» (14:39)."),
"prophets_253": ("Welke profeet heeft Allah tot Zich opgeheven?", ["Isa", "Yunus", "Ayyub", "Idris"], "«Nee, Allah heeft hem tot Zich opgeheven» (4:158)."),
"prophets_254": ("Wie is de moeder van de profeet Isa?", ["Maryam", "Asiya", "Hajar", "Sara"], "Maryam, aan wie een hele soera van de Koran is gewijd."),
"prophets_255": ("Wie is de eerste mens die Allah schiep?", ["Adam", "Nuh", "Ibrahim", "Idris"], "Adam is de eerste mens, aan wie Allah alle namen leerde."),
"prophets_256": ("Voor welke profeet werd het vuur koelte en vrede?", ["Ibrahim", "Musa", "Yusuf", "Sulayman"], "«O vuur, wees koelte en vrede voor Ibrahim.»"),
"prophets_257": ("Welke profeet droeg een staf die in een slang veranderde?", ["Musa", "Harun", "Yahya", "Zakariyya"], "Allah vroeg Musa: «En wat is dat in jouw rechterhand?»"),
"prophets_258": ("Welke profeet droomde van elf sterren die zich neerwierpen?", ["Yusuf", "Ya'qub", "Ishaq", "Dawud"], "«O mijn vader, ik zag elf sterren, de zon en de maan.»"),
"prophets_259": ("Welke vogel bracht nieuws aan de profeet Sulayman?", ["De hop", "De kraai", "De valk", "De duif"], "De hop zei: «Ik breng je zeker nieuws uit Saba» (27:22)."),
"prophets_260": ("Welke profeet is het voorbeeld van geduld in beproeving?", ["Ayyub", "Yunus", "Lut", "Shu'ayb"], "Ayyub riep zijn Heer aan en werd standvastig bevonden."),
"prophets_261": ("Waaruit schiep Allah Adam?", ["Uit stof", "Uit licht", "Uit vuur", "Uit wind"], "«Hij schiep hem uit stof en zei toen tot hem: Wees!» (3:59)."),
"prophets_262": ("Tot welke profeet sprak Allah rechtstreeks?", ["Musa", "Yusuf", "Yunus", "Salih"], "«En Allah sprak tot Musa met rechtstreekse spraak.»"),
"prophets_263": ("Hoeveel profeten komen er na Muhammad ﷺ?", ["Geen: hij is de laatste van de profeten", "Eén", "Drie", "Zeven"], "Muhammad ﷺ is het zegel van de profeten: na hem komt geen profeet meer."),
"prophets_264": ("Welke profeet wordt de boezemvriend (khalil) van Allah genoemd?", ["Ibrahim", "Musa", "Isa", "Nuh"], "Ibrahim is de vader van de profeten en de boezemvriend van de Meest Barmhartige."),
"prophets_265": ("Welke profeet genas met Allahs toestemming de blindgeborene?", ["Isa", "Yahya", "Zakariyya", "Ilyas"], "«En jij genas de blindgeborene en de melaatse met Mijn toestemming.»"),
"prophets_266": ("Voor welke profeet herhaalden de bergen de lofprijzing van Allah?", ["Dawud", "Sulayman", "Ayyub", "Yunus"], "«O bergen, herhaal met hem de lofprijzing van Allah.»"),
"prophets_267": ("Welke profeet legde de droom van de koning van Egypte uit?", ["Yusuf", "Harun", "Ilyas", "Shu'ayb"], "Yusuf legde de droom van de zeven vette en de zeven magere koeien uit (12:46-49)."),
"prophets_268": ("Wie is de vader van de profeet Yusuf?", ["Ya'qub", "Ishaq", "Ibrahim", "Lut"], "Yusuf is de zoon van Ya'qub, die zelf de zoon van Ishaq is."),
"prophets_269": ("Wat spleet voor Musa en zijn volk?", ["De zee, gespleten om hen van de Farao te redden", "Een rivier van Egypte", "Een meer van Madyan", "Een put in de woestijn"], "«En toen Wij de zee voor jullie spleten en jullie redden.»"),
"prophets_270": ("Wat zegt men na het noemen van de naam van de Profeet ﷺ?", ["«Allahs zegeningen en vrede zij met hem»", "Niets in het bijzonder", "«Dank je wel»", "«Tot ziens»"], "Men vraagt zegeningen en vrede over hem: salla-Llahu 'alayhi wa sallam."),
"prophets_271": ("Welke profeet riep zijn volk heel lang op, vóór de zondvloed?", ["Nuh", "Hud", "Salih", "Shu'ayb"], "«Wij zonden Nuh naar zijn volk: waarschuw jouw volk.»"),
"prophets_272": ("Van welke profeet is Sulayman de zoon?", ["Dawud", "Ya'qub", "Ishaq", "Yunus"], "«En aan Dawud schonken Wij Sulayman: een voortreffelijke dienaar!» (38:30)."),
"prophets_273": ("Welke profeet versloeg Jalut (Goliath)?", ["Dawud", "Sulayman", "Yusha'", "Ilyas"], "«En Dawud doodde Jalut» (2:251)."),
"prophets_274": ("In hoeveel profeten moet een moslim geloven?", ["In allemaal, zonder onderscheid te maken", "Alleen in de laatste", "Alleen in drie", "Alleen in wie in de Koran genoemd worden"], "Een moslim gelooft in alle profeten van Allah, zonder onderscheid tussen hen te maken."),
"prophets_275": ("Wie heeft Allah uitverkoren, volgens de Koran?", ["Adam, Nuh, de familie van Ibrahim en de familie van 'Imran", "De koningen van Egypte", "De stammen van Medina", "Het volk van Saba"], "«Allah verkoos Adam en Nuh en de familie van Ibrahim en de familie van 'Imran.»"),
"prophets_276": ("In welk land werd de profeet Yusuf de vertrouweling van de koning?", ["Egypte", "Sham", "Jemen", "Irak"], "Yusuf kreeg een vaste plaats in Egypte nadat hij de droom van de koning had uitgelegd."),
"prophets_277": ("Welke profeet werd 's nachts naar de Al-Aqsa-moskee gebracht?", ["Muhammad ﷺ", "Musa", "Isa", "Ibrahim"], "«Verheven is Hij die Zijn dienaar 's nachts liet reizen.»"),
"prophets_278": ("Welk boek werd aan de profeet Musa gegeven?", ["De Thora", "Het Evangelie", "De Psalmen", "De Bladen van Ibrahim"], "Allah gaf Musa het Boek en liet na hem boodschappers volgen."),
"prophets_279": ("Welk boek werd aan de profeet Isa gegeven?", ["Het Evangelie", "De Thora", "De Psalmen", "De Koran"], "«En Wij gaven hem het Evangelie, waarin leiding en licht was.»"),
"prophets_280": ("Welk boek werd aan de profeet Dawud gegeven?", ["De Psalmen (Zabur)", "De Thora", "Het Evangelie", "De Bladen van Musa"], "«En aan Dawud gaven Wij de Zabur.»"),
"prophets_281": ("De zoon van welke profeet stemde ermee in geofferd te worden, uit gehoorzaamheid aan Allah?", ["De zoon van Ibrahim", "De zoon van Nuh", "De broer van Musa", "De zoon van Ya'qub"], "«O mijn vader, doe wat jou bevolen is: je zult mij geduldig vinden.»"),
"prophets_282": ("Waar legde de moeder van Musa haar baby neer om hem te redden?", ["In de rivier", "In een grot", "Bij een buurvrouw", "In de woestijn"], "«Leg hem in de rivier: Wij zullen hem naar jou terugbrengen.»"),
"prophets_283": ("Wat zei Yunus in de duisternis, wat elke moslim herhaalt?", ["«Er is geen god dan U, geprezen zij U, ik behoorde tot de onrechtplegers»", "«Geef mij rijkdom»", "«Maak mij koning»", "«Maak mij sterk»"], "De smeekbede van Yunus in de buik van de vis."),
"prophets_284": ("Wie is de vader van de Profeet Muhammad ﷺ?", ["'Abdullah", "Abu Talib", "Al-'Abbas", "Hamza"], "Hij is Muhammad ﷺ, zoon van 'Abdullah, zoon van 'Abd al-Muttalib."),
"prophets_285": ("Wie is de moeder van de Profeet Muhammad ﷺ?", ["Amina", "Khadija", "'Aisha", "Fatima"], "Amina bint Wahb is de moeder van de Profeet ﷺ."),
"prophets_286": ("Wat zei Isa toen hij nog in de wieg lag?", ["«Ik ben de dienaar van Allah»", "«Ik ben een koning»", "«Ik ben een engel»", "Hij zei niets"], "«Voorwaar, ik ben de dienaar van Allah: Hij heeft mij het Boek gegeven.»"),
"prophets_287": ("Welke profeet werd naar het volk van 'Ad gezonden?", ["Hud", "Salih", "Lut", "Shu'ayb"], "«En tot de 'Ad, hun broeder Hud.»"),
"prophets_288": ("Welke profeet werd naar de Thamud gezonden, met de kameelmerrie?", ["Salih", "Hud", "Yunus", "Idris"], "«En tot de Thamud, hun broeder Salih: dit is de kameelmerrie van Allah.»"),
"prophets_289": ("Welke profeet is de broer van Musa, samen met hem gezonden?", ["Harun", "Yusuf", "Yahya", "Ilyas"], "«En geef mij een helper uit mijn familie: Harun, mijn broer.»"),
"prophets_290": ("Welke titel geeft de Koran aan Muhammad ﷺ met betrekking tot de profeten?", ["Het zegel van de profeten", "De eerste van de profeten", "De koning van de profeten", "De schrijver van de profeten"], "«Muhammad is de Boodschapper van Allah en het zegel van de profeten.»"),
"prophets_291": ("Wat zeggen de engelen tegen Maryam in de Koran?", ["Dat Allah haar heeft uitverkoren en gereinigd", "Dat zij koningin zal worden", "Dat zij zal reizen", "Dat zij les zal geven"], "«O Maryam, Allah heeft jou uitverkoren en jou gereinigd.»"),
"prophets_292": ("Hoe riep Ayyub zijn Heer aan in zijn beproeving?", ["«Tegenspoed heeft mij getroffen, en U bent de Meest Barmhartige»", "«Maak mij rijk»", "«Straf mijn vijanden»", "«Maak mij koning»"], "«Tegenspoed heeft mij getroffen, en U bent de Barmhartigste van de barmhartigen.»"),
"prophets_293": ("Wat leerde Allah aan Adam?", ["Alle namen", "Schrijven", "Zeevaart", "Rekenen"], "«En Hij leerde Adam alle namen.»"),
"prophets_294": ("Welke profeet heerste over een koninkrijk dat niemand na hem zou hebben?", ["Sulayman", "Dawud", "Yusuf", "Dhul-Qarnayn"], "«Schenk mij een koninkrijk dat aan niemand na mij zal toekomen.»"),
"prophets_295": ("Welke profeet werd met zijn familie gered, behalve zijn vrouw?", ["Lut", "Nuh", "Hud", "Salih"], "«Vertrek met jouw familie in een deel van de nacht… behalve jouw vrouw.»"),
"prophets_296": ("Waarvoor waarschuwde Ibrahim zijn volk?", ["Het aanbidden van afgoden", "Handel drijven", "Reizen", "Schrijven"], "«Nemen jullie afgoden als goden?»"),
"prophets_297": ("Welk woord betekent: iemand die door Allah naar de mensen is gezonden?", ["Een boodschapper (rasul)", "Een kalief", "Een metgezel", "Een geleerde"], "Een rasul is iemand die door Allah is gezonden, belast met een boodschap voor de mensheid."),
"prophets_298": ("Als wat zond Allah de Profeet ﷺ, volgens soera Al-Ahzab?", ["Als getuige, brenger van goed nieuws en waarschuwer", "Als koning en rechter", "Als koopman", "Als dichter"], "«O Profeet, Wij hebben jou gezonden als getuige, als brenger van goede tijding en als waarschuwer» (33:45)."),
"prophets_299": ("Waarom werd Muhammad ﷺ gezonden, volgens de Koran?", ["Als barmhartigheid voor de werelden", "Om te heersen", "Om te bouwen", "Om handel te drijven"], "«En Wij hebben jou slechts gezonden als barmhartigheid voor de werelden.»"),
"prophets_300": ("Welke profeet noemt de Koran «een zeer dankbare dienaar»?", ["Nuh", "Lut", "Idris", "Ilyas"], "«Voorwaar, hij was een dankbare dienaar» (17:3), gezegd over Nuh."),
"prophets_301": ("Welk teken kreeg Zakariyya na het nieuws over zijn zoon?", ["Drie dagen niet tot de mensen spreken", "Een ster zien", "Donder horen", "Over water lopen"], "«Jouw teken is dat je drie dagen niet tot de mensen zult spreken» (3:41)."),
"prophets_302": ("In welke taal werd elke boodschapper gezonden?", ["In de taal van zijn eigen volk", "Alleen in het Arabisch", "In het Hebreeuws", "In een hemelse taal"], "«Wij zonden geen boodschapper dan in de taal van zijn volk.»"),
"prophets_303": ("Welke soera vertelt het verhaal van één profeet van begin tot eind?", ["Soera Yusuf", "Soera Al-Baqara", "Soera An-Nas", "Soera Al-Fatiha"], "«Wij vertellen jou het mooiste van de verhalen»: het verhaal van Yusuf."),
"prophets_304": ("Hoe beschrijft de Koran Ibrahim in soera Maryam?", ["Een waarachtig man, een profeet", "Een koning", "Een schrijver", "Een koopman"], "«Hij was een waarachtige, een profeet.»"),
"prophets_305": ("Welke koningin kwam de profeet Sulayman bezoeken?", ["De koningin van Saba", "De koningin van Egypte", "De koningin van Babylon", "De koningin van Noord-Jemen"], "Zij onderwierp zich samen met Sulayman aan Allah, de Heer van de werelden."),
"prophets_306": ("Welke profeet vroeg om te zien hoe Allah de doden weer tot leven wekt?", ["Ibrahim", "Musa", "Nuh", "Yunus"], "«Mijn Heer, toon mij hoe U de doden tot leven wekt.»"),
"prophets_307": ("Welke profeet reisde om te leren van een dienaar met kennis?", ["Musa", "Yusuf", "Dawud", "Sulayman"], "Musa reisde tot hij een dienaar van Allah ontmoette aan wie Hij kennis had gegeven."),
"prophets_308": ("Wat leert soera Al-Ikhlas over Allah?", ["Dat Hij Eén is, en dat niemand aan Hem gelijk is", "Dat Hij deelgenoten heeft", "Dat Hij op Zijn schepping lijkt", "Dat Hij een zoon heeft"], "«Zeg: Hij is Allah, de Ene… en niemand is aan Hem gelijk.»"),
"prophets_309": ("Hoe noemden de Mekkanen de Profeet ﷺ vóór de openbaring?", ["Al-Amin, de betrouwbare", "De reiziger", "De dichter", "De rechter"], "Zijn eerlijkheid was zo bekend dat hij al-Amin werd genoemd."),
"prophets_310": ("Wie stelt de Koran voor als het beste voorbeeld om te volgen?", ["De Boodschapper van Allah ﷺ", "Koningen", "Dichters", "Kooplieden"], "«Voorzeker, in de Boodschapper van Allah hebben jullie een prachtig voorbeeld.»"),
"sira_251": ("In welke stad werd de Profeet ﷺ geboren?", ["Mekka", "Medina", "Jeruzalem", "Ta'if"], "De Profeet ﷺ werd geboren in Mekka, in de stam Quraysh."),
"sira_252": ("Naar welke stad emigreerde de Profeet ﷺ?", ["Medina", "Ta'if", "Caïro", "Damascus"], "De Hijra ging van Mekka naar Medina, dat toen Yathrib heette."),
"sira_253": ("Hoe heet de verhuizing van Mekka naar Medina?", ["De Hijra", "De bedevaart", "De verovering", "Het verbond"], "De Hijra markeert het begin van de islamitische kalender."),
"sira_254": ("Wie is de eerste vrouw van de Profeet ﷺ?", ["Khadija", "'Aisha", "Hafsa", "Sawda"], "Khadija bint Khuwaylid, de eerste die in hem geloofde."),
"sira_255": ("In welke grot verborg de Profeet ﷺ zich tijdens de Hijra?", ["De grot Thawr", "De grot Hira", "De grot Uhud", "De grot Quba"], "Hij verborg zich daar drie dagen met Abu Bakr voordat hij verder reisde naar Medina."),
"sira_256": ("Wat is het eerste woord dat aan de Profeet ﷺ werd geopenbaard?", ["«Lees»", "«Bid»", "«Sta op»", "«Luister»"], "«Lees, in de naam van jouw Heer die schiep.»"),
"sira_257": ("Welke engel bracht de openbaring aan de Profeet ﷺ?", ["Jibril", "Mika'il", "Israfil", "Malik"], "Jibril is de engel die belast is met het neerbrengen van de openbaring."),
"sira_258": ("In welke stad is het graf van de Profeet ﷺ?", ["Medina", "Mekka", "Jeruzalem", "Ta'if"], "Zijn graf is in Medina, naast zijn moskee."),
"sira_259": ("Uit welke stam kwam de Profeet ﷺ?", ["Quraysh", "Aws", "Khazraj", "Thaqif"], "De Profeet ﷺ behoorde tot Quraysh, de stam van Mekka."),
"sira_260": ("Hoe heten de metgezellen van de Profeet ﷺ?", ["De Sahaba", "De Tabi'un", "Alleen de Ansar", "De Qurra"], "De Sahaba zijn degenen die de Profeet ﷺ zagen terwijl zij in hem geloofden."),
"sira_261": ("Wie vergezelde de Profeet ﷺ tijdens de Hijra?", ["Abu Bakr", "'Umar", "'Uthman", "Bilal"], "Abu Bakr was zijn metgezel in de grot tijdens de Hijra."),
"sira_262": ("Wie riep voor de Profeet ﷺ op tot het gebed?", ["Bilal", "Anas", "Zayd", "Salman"], "Bilal ibn Rabah riep in Medina op tot het gebed."),
"sira_263": ("Hoe heet de eerste slag van de islam?", ["Badr", "Uhud", "Khaybar", "Hunayn"], "Badr is de eerste grote slag, in het tweede jaar van de Hijra."),
"sira_264": ("Hoe heten degenen die van Mekka naar Medina emigreerden?", ["De Muhajirun", "De Ansar", "De Tabi'un", "De metgezellen van Ta'if"], "De Muhajirun zijn de emigranten; de Ansar zijn degenen die hen ontvingen."),
"sira_265": ("Hoe heten de mensen van Medina die de emigranten ontvingen?", ["De Ansar", "De Muhajirun", "Quraysh", "De Tabi'un"], "De Ansar, «de helpers», zijn de Aws en de Khazraj van Medina."),
"sira_266": ("Wat bouwde de Profeet ﷺ als eerste in Medina?", ["Een moskee", "Een markt", "Een paleis", "Een muur"], "Hij bouwde zijn moskee zodra hij in Medina aankwam."),
"sira_267": ("Welke dochter van de Profeet ﷺ trouwde met 'Ali?", ["Fatima", "Ruqayya", "Zaynab", "Umm Kulthum"], "Fatima, de dochter van de Profeet ﷺ, trouwde met 'Ali ibn Abi Talib."),
"sira_268": ("Wie was de eerste kalief na de Profeet ﷺ?", ["Abu Bakr", "'Umar", "'Uthman", "'Ali"], "Abu Bakr as-Siddiq was de eerste kalief."),
"sira_269": ("Hoe heette Medina vroeger?", ["Yathrib", "Bakka", "Ta'if", "Khaybar"], "Yathrib kreeg de naam Madinat an-Nabi, de stad van de Profeet ﷺ."),
"sira_270": ("Hoe oud was de Profeet ﷺ bij de eerste openbaring?", ["Veertig jaar", "Twintig", "Zestig", "Dertig"], "De openbaring kwam tot hem toen hij veertig jaar oud was."),
"sira_271": ("In welke stad staat de Ka'ba?", ["Mekka", "Medina", "Jeruzalem", "Damascus"], "De Ka'ba staat in het midden van de Heilige Moskee, in Mekka."),
"sira_272": ("In welke stad staat de Al-Aqsa-moskee?", ["Jeruzalem", "Mekka", "Medina", "Caïro"], "De Al-Aqsa-moskee staat in Jeruzalem (al-Quds)."),
"sira_273": ("Welke oom van de Profeet ﷺ beschermde hem in Mekka?", ["Abu Talib", "Abu Lahab", "Al-'Abbas", "Abu Sufyan"], "Abu Talib, de vader van 'Ali, beschermde zijn neef tegen Quraysh."),
"sira_274": ("Wat was het beroep van Khadija, de eerste vrouw van de Profeet ﷺ?", ["Koopvrouw", "Arts", "Dichteres", "Weefster"], "Khadija was een gerespecteerde koopvrouw van Mekka."),
"sira_275": ("Hoe heet de laatste bedevaart van de Profeet ﷺ?", ["De Afscheidsbedevaart", "De eerste bedevaart", "De bedevaart van de verovering", "De kleine bedevaart"], "De Afscheidsbedevaart vond plaats in het jaar 10 van de Hijra."),
"sira_276": ("Hoe heet het verhaal van het leven van de Profeet ﷺ?", ["De Sira", "De Soenna", "De Tafsir", "De Fiqh"], "De Sira is het verhaal van zijn leven; de Soenna is wat hij zei en deed."),
"sira_277": ("Hoe heet een uitspraak die van de Profeet ﷺ is overgeleverd?", ["Een hadith", "Een soera", "Een vers", "Een smeekbede"], "Een hadith is een uitspraak, handeling of goedkeuring van de Profeet ﷺ."),
"sira_278": ("Welke twee hadithverzamelingen worden als de meest betrouwbare beschouwd?", ["Sahih al-Bukhari en Sahih Muslim", "Twee dichtbundels", "Twee geschiedenisboeken", "Twee woordenboeken"], "Samen worden zij «de twee Sahihs» genoemd."),
"sira_279": ("Welke kalief liet de Koran kopiëren en naar de provincies sturen?", ["'Uthman", "Abu Bakr", "'Umar", "'Ali"], "'Uthman liet officiële kopieën maken en naar de belangrijkste steden sturen."),
"sira_280": ("Hoeveel kaliefen zijn «de rechtgeleide kaliefen»?", ["Vier", "Twee", "Zeven", "Twaalf"], "Abu Bakr, 'Umar, 'Uthman en 'Ali."),
"sira_281": ("In welke richting bidden moslims?", ["Naar de Ka'ba, in Mekka", "Naar Jeruzalem", "Naar het oosten", "Naar Medina"], "De qibla is de richting van de Ka'ba."),
"sira_282": ("Hoe heet die gebedsrichting?", ["De qibla", "De mihrab", "De minbar", "De minaret"], "De qibla is de richting; de mihrab is de nis die haar aangeeft."),
"sira_283": ("Hoe heet de plaats waar moslims samen bidden?", ["De moskee", "De school", "De markt", "De bibliotheek"], "De masjid is de plaats van neerwerping, de moskee."),
"sira_284": ("Hoe heet de oproep tot het gebed?", ["De adhan", "De takbir", "De tasbih", "De dhikr"], "De adhan is de oproep; wie hem roept, is de muezzin."),
"sira_285": ("Op welke dag komen moslims samen voor het grote gebed?", ["Vrijdag", "Zaterdag", "Zondag", "Maandag"], "Het vrijdaggebed (al-jumu'a) brengt de gemeenschap elke week samen."),
"sira_286": ("Hoe heet degene die het gebed leidt?", ["De imam", "De muezzin", "De rechter", "De hafiz"], "De imam is degene achter wie de gelovigen in rijen gaan staan om te bidden."),
"sira_287": ("Hoe heet iemand die de hele Koran uit het hoofd kent?", ["Een hafiz", "Een imam", "Een muezzin", "Een rechter"], "Een hafiz is iemand die de hele Koran in zijn geheugen bewaart."),
"sira_288": ("Welke metgezel staat bekend als de grootste overleveraar van hadith?", ["Abu Hurayra", "Bilal", "Salman", "Anas"], "Abu Hurayra bracht de laatste jaren van de Profeet ﷺ aan zijn zijde door."),
"sira_289": ("Welke kalief wordt as-Siddiq genoemd, «de waarachtige»?", ["Abu Bakr", "'Umar", "'Uthman", "'Ali"], "Abu Bakr as-Siddiq, de eerste vrije man die geloofde."),
"sira_290": ("Welke kalief wordt al-Faruq genoemd?", ["'Umar ibn al-Khattab", "Abu Bakr", "'Uthman", "'Ali"], "'Umar, die waarheid van leugen onderscheidde, kreeg die titel."),
"sira_291": ("Welke kalief liet de Koran in één boek verzamelen?", ["Abu Bakr", "Mu'awiya", "Khalid", "Bilal"], "Abu Bakr gaf opdracht om alles wat opgeschreven was bijeen te brengen."),
"sira_292": ("Welke grootvader voedde de Profeet ﷺ als kind op?", ["'Abd al-Muttalib", "Abu Sufyan", "Al-Walid", "'Utba"], "Zijn grootvader 'Abd al-Muttalib nam hem na zijn geboorte onder zijn hoede."),
"sira_293": ("Hoe herinnert de Koran aan de kindertijd van de Profeet ﷺ?", ["Allah vond hem als wees en gaf hem onderdak", "Hij was een koning", "Hij was rijk van kinds af aan", "Hij leefde alleen in de woestijn"], "«Heeft Hij jou niet als wees gevonden en jou onderdak gegeven?» (93:6)."),
"sira_294": ("Welke slag kwam na Badr?", ["Uhud", "De Gracht", "Hunayn", "Tabuk"], "Het jaar daarna kwam de slag bij Uhud, dicht bij Medina."),
"sira_295": ("Wat groeven de moslims rond Medina om de stad te verdedigen?", ["Een gracht (al-Khandaq)", "Een put", "Een tunnel", "Een kanaal"], "Zij groeven een gracht, die de Slag van de Gracht haar naam gaf."),
"sira_296": ("Van wie was 'Aisha, de vrouw van de Profeet ﷺ, de dochter?", ["Van Abu Bakr", "Van 'Umar", "Van 'Uthman", "Van 'Ali"], "'Aisha was de dochter van Abu Bakr as-Siddiq."),
"sira_297": ("Hoe noemt de Koran de vrouwen van de Profeet ﷺ?", ["De moeders van de gelovigen", "De dienaressen", "De reisgenoten", "De geëmigreerde vrouwen"], "«En zijn vrouwen zijn hun moeders» (33:6)."),
"sira_298": ("Welke metgezel was zowel een neef als een schoonzoon van de Profeet ﷺ?", ["'Ali ibn Abi Talib", "Bilal", "Salman", "Zayd"], "'Ali, de neef van de Profeet ﷺ, trouwde met zijn dochter Fatima."),
"sira_299": ("Hoe heet de moskee van de Profeet ﷺ in Medina?", ["Al-Masjid an-Nabawi", "Al-Masjid al-Haram", "Al-Aqsa", "Quba"], "De Moskee van de Profeet, an-Nabawi, staat in Medina."),
"sira_300": ("Hoe heet het rijdier van de nachtreis van de Profeet ﷺ?", ["Al-Buraq", "Al-'Adba'", "Ash-Shaqra'", "Al-Qaswa'"], "Het rijdier van de nachtreis heet al-Buraq."),
"faith_151": ("Hoeveel zuilen heeft de islam?", ["Vijf", "Drie", "Zes", "Tien"], "Vijf: de geloofsgetuigenis, het gebed, de zakat, het vasten en de bedevaart."),
"faith_152": ("Wat is de eerste zuil van de islam?", ["De geloofsgetuigenis (shahada)", "Het vasten", "De bedevaart", "De zakat"], "Men treedt toe tot de islam door te getuigen dat er geen god is dan Allah en dat Muhammad ﷺ Zijn boodschapper is."),
"faith_153": ("Hoeveel verplichte gebeden verricht een moslim per dag?", ["Vijf", "Drie", "Zeven", "Twee"], "Vijf gebeden, verspreid van de dageraad tot de nacht."),
"faith_154": ("In welke maand vasten moslims?", ["Ramadan", "Rajab", "Sha'ban", "Shawwal"], "«De maand Ramadan, waarin de Koran werd neergezonden» (2:185)."),
"faith_155": ("Hoe heet de verplichte liefdadigheid van de islam?", ["Zakat", "Du'a", "Dhikr", "Tawaf"], "De zakat is het deel van je bezit dat je elk jaar weggeeft."),
"faith_156": ("Hoe heet de grote bedevaart naar Mekka?", ["De hajj", "De sa'y", "De dhikr", "De suhur"], "De hajj is de bedevaart die wie ertoe in staat is eenmaal in het leven verricht."),
"faith_157": ("Hoeveel geloofsartikelen (arkan al-iman) zijn er?", ["Zes", "Vier", "Vijf", "Zeven"], "Het geloof in Allah, Zijn engelen, Zijn boeken, Zijn boodschappers, de Laatste Dag en de voorbeschikking."),
"faith_158": ("In hoeveel goden gelooft een moslim?", ["In één alleen", "In twee", "In drie", "In vele"], "«Zeg: Hij is Allah, de Ene» (112:1)."),
"faith_159": ("Hoe noemen moslims God in het Arabisch?", ["Allah", "Malak", "Rasul", "Nabi"], "Allah is de naam van de Schepper in het Arabisch."),
"faith_160": ("Hoe heet het heilige boek van de moslims?", ["De Koran", "De Tawrat", "De Injil", "De Zabur"], "De Koran is het boek dat aan de Profeet Muhammad ﷺ werd geopenbaard."),
"faith_161": ("Hoe heet het Huis van Allah dat in Mekka is gebouwd?", ["De Ka'ba", "De Rawda", "De Maqam", "De Hijr"], "«Het eerste Huis dat voor de mensen werd gesticht, is dat in Bakka» (3:96)."),
"faith_162": ("Wat zegt een moslim voordat hij begint te eten?", ["Bismillah", "Amin", "Subhan Allah", "Allahumma"], "De Profeet ﷺ leerde een jongen: «Zeg Bismillah, en eet met je rechterhand.»"),
"faith_163": ("Hoe groeten moslims elkaar?", ["As-salamu 'alaykum", "Al-hamdu lillah", "Bismillah", "Allahu akbar"], "«As-salamu 'alaykum» betekent: vrede zij met jullie."),
"faith_164": ("Wat is het antwoord op «as-salamu 'alaykum»?", ["Wa 'alaykum as-salam", "Bismillah", "Amin", "Subhan Allah"], "De groet wordt beantwoord: «en met jullie zij vrede»."),
"faith_165": ("Hoe heet het feest direct na de maand Ramadan?", ["Eid al-Fitr", "Eid al-Adha", "Laylat al-Qadr", "'Ashura"], "Eid al-Fitr, het feest van het verbreken van het vasten."),
"faith_166": ("Hoe heet het offerfeest?", ["Eid al-Adha", "Eid al-Fitr", "De Mawlid", "Laylat al-Qadr"], "Eid al-Adha valt tijdens de dagen van de bedevaart."),
"faith_167": ("Hoe heten de schepselen van Allah die Hem altijd gehoorzamen en nooit ongehoorzaam zijn?", ["De engelen", "De djinn", "De profeten", "De metgezellen"], "De engelen voeren uit wat Allah beveelt en zijn nooit ongehoorzaam."),
"faith_168": ("Hoe heet het Paradijs in het Arabisch?", ["Al-Janna", "As-Salat", "Ad-Du'a", "Al-Adhan"], "Al-Janna, letterlijk «de tuin», is het huis dat aan de gelovigen is beloofd."),
"faith_169": ("Hoe heet het wassen met water dat vóór het gebed wordt gedaan?", ["De rituele wassing (wudu')", "De tawaf", "De dhikr", "De sa'y"], "De wudu' is de reiniging die aan het gebed voorafgaat."),
"faith_170": ("Hoe heet één eenheid van het gebed?", ["Een rak'a", "Een soera", "Een adhan", "Een tawaf"], "Een rak'a bevat het staan, het buigen en de neerwerpingen."),
"faith_171": ("Welke soera wordt in elke eenheid van het gebed gereciteerd?", ["Al-Fatiha", "Al-Ikhlas", "An-Nas", "Al-Kawthar"], "Al-Fatiha, de openingssoera, wordt in elke rak'a gereciteerd."),
"faith_172": ("Hoe heet wat in de islam toegestaan is?", ["Halal", "Haram", "Soenna", "Fard"], "Halal betekent: wat toegestaan is."),
"faith_173": ("Hoe heet wat in de islam verboden is?", ["Haram", "Halal", "Mubah", "Nafila"], "Haram betekent: wat verboden is."),
"faith_174": ("Welk vlees verbiedt de Koran?", ["Varkensvlees", "Lamsvlees", "Rundvlees", "Kip"], "«Hij heeft jullie het kadaver, het bloed en het vlees van het varken verboden» (2:173)."),
"faith_175": ("Welke drank gebiedt de Koran ons te vermijden?", ["Wijn en elke bedwelmende drank", "Melk", "Honing", "Regenwater"], "«Wijn, gokken… zijn een gruwel, vermijd ze dus» (5:90)."),
"faith_176": ("Wat zegt degene die niest, zoals de Profeet ﷺ leerde?", ["Al-hamdu lillah", "Bismillah", "Allahu akbar", "Amin"], "«Wanneer een van jullie niest, laat hij dan zeggen: al-hamdu lillah.»"),
"faith_177": ("Hoe zeg je «het gebed» in het Arabisch?", ["As-salat", "As-sawm", "Az-zakat", "Al-hajj"], "As-salat is het rituele gebed van de moslim."),
"faith_178": ("Hoe heet het wanneer je Allah in je eigen woorden om iets vraagt?", ["Du'a", "Tawaf", "Adhan", "Sa'y"], "Du'a is de smeekbede, het aanroepen van Allah."),
"faith_179": ("Wat betekent «al-hamdu lillah»?", ["Alle lof zij Allah", "Allah is de grootste", "In de naam van Allah", "Glorie zij Allah"], "Het is het tweede vers van Al-Fatiha: «Alle lof zij Allah, de Heer van de werelden» (1:2)."),
"faith_180": ("Wat betekent het woord «islam»?", ["Overgave aan Allah", "Rijkdom", "Reizen", "Kennis"], "Islam komt van een wortel die «zich overgeven» en «in vrede zijn» betekent."),
"faith_181": ("Wat betekent het woord «moslim»?", ["Iemand die zich aan Allah overgeeft", "Iemand die reist", "Iemand die lesgeeft", "Iemand die bouwt"], "Een moslim is iemand die zich alleen aan Allah overgeeft."),
"faith_182": ("Wie schiep de hemelen en de aarde, volgens de Koran?", ["Allah", "De engelen", "De profeten", "De zon"], "«Alle lof zij Allah, die de hemelen en de aarde schiep» (6:1)."),
"faith_183": ("Hoeveel namen van Allah noemt de hadith?", ["Negenennegentig", "Tien", "Vijftig", "Duizend"], "«Allah heeft negenennegentig namen, honderd min één.»"),
"faith_184": ("Wat doen de engelen die «edele schrijvers» worden genoemd?", ["Zij schrijven onze daden op", "Zij dragen de regen", "Zij bewaken de Ka'ba", "Zij geven les in het Arabisch"], "«Edele schrijvers, die weten wat jullie doen» (82:11-12)."),
"faith_185": ("Welke nacht beschrijft de Koran als beter dan duizend maanden?", ["Laylat al-Qadr", "De vrijdagnacht", "De nacht van Eid", "De eerste nacht van Ramadan"], "«De Nacht van de Beschikking is beter dan duizend maanden» (97:3)."),
"faith_186": ("Hoe heet het geloof in één enige God?", ["Tawhid", "Tawaf", "Tayammum", "Tarawih"], "Tawhid is de eenheid van Allah, het hart van de boodschap van elke profeet."),
"faith_187": ("Hoe heet het toekennen van een deelgenoot aan Allah in de aanbidding?", ["Shirk", "Dhikr", "Du'a", "Sabr"], "Shirk is het toekennen van deelgenoten: iets naast Allah aanbidden."),
"faith_188": ("Hoe heet de dag waarop iedereen geoordeeld zal worden?", ["De Dag der Opstanding", "De dag van Eid", "Vrijdag", "De eerste dag van Ramadan"], "Yawm al-Qiyama, de Dag der Opstanding, waarop iedereen zijn daden zal zien."),
"faith_189": ("Hoeveel maanden telt het jaar volgens de Koran?", ["Twaalf", "Tien", "Veertien", "Zes"], "«Het aantal maanden bij Allah is twaalf» (9:36)."),
"faith_190": ("Hoeveel neerwerpingen zijn er in één rak'a?", ["Twee", "Eén", "Drie", "Vier"], "Elke rak'a bevat twee neerwerpingen."),
"quran_151": ("Hoeveel soera's bevat de Koran?", ["Honderdveertien", "Zestig", "Tweehonderd", "Dertig"], "De Koran heeft 114 soera's, van Al-Fatiha tot An-Nas."),
"quran_152": ("Wat is de eerste soera van de Koran?", ["Al-Fatiha", "Al-Baqara", "An-Nas", "Ya-Sin"], "Al-Fatiha, «de opening», is de eerste soera."),
"quran_153": ("Wat betekent het woord «Koran»?", ["De recitatie, de lezing", "Het pad", "Het licht", "De tuin"], "Koran komt van een wortel die «lezen» en «reciteren» betekent."),
"quran_154": ("Over ongeveer hoeveel jaar werd de Koran neergezonden?", ["Ongeveer drieëntwintig jaar", "Eén enkele nacht", "Honderd jaar", "Drie jaar"], "De openbaring kwam neer over een periode van zo'n drieëntwintig jaar."),
"quran_155": ("Hoe heet een vers van de Koran?", ["Een aya", "Een soera", "Een juz'", "Een hadith"], "Elke genummerde zin van de Koran is een aya, een «teken»."),
"quran_156": ("Hoe heet een hoofdstuk van de Koran?", ["Een soera", "Een aya", "Een juz'", "Een khutba"], "De Koran is verdeeld in soera's, elk met een eigen naam."),
"quran_157": ("Wat is de langste soera van de Koran?", ["Al-Baqara", "Al-Fatiha", "Al-Kawthar", "An-Nas"], "Al-Baqara is de langste soera van de Koran."),
"quran_158": ("Wat is de kortste soera van de Koran?", ["Al-Kawthar", "Al-Baqara", "Al-'Imran", "An-Nisa'"], "Al-Kawthar heeft maar drie verzen."),
"quran_159": ("Welke zin opent bijna elke soera?", ["In de naam van Allah, de Erbarmer, de Meest Barmhartige", "Alle lof zij Allah", "Allah is de grootste", "Er is geen god dan Allah"], "De basmala opent 113 van de 114 soera's."),
"quran_160": ("Wiens woord is de Koran?", ["Van Allah", "Van de Profeet ﷺ", "Van de engel Jibril", "Van de metgezellen"], "De Koran noemt zichzelf «het woord van Allah» (kalam Allah) in 9:6."),
"quran_161": ("In hoeveel delen (juz') is de Koran verdeeld?", ["Dertig", "Tien", "Vijftig", "Honderd"], "De Koran is verdeeld in dertig juz', één voor elke nacht van de Ramadan."),
"quran_162": ("Welke soera draagt de naam van een vrouw?", ["Maryam", "Yusuf", "Nuh", "Muhammad"], "Soera 19 draagt de naam van Maryam."),
"quran_163": ("Hoe heten de laatste twee soera's, waarmee men bescherming zoekt?", ["Al-Mu'awwidhatan", "Al-Mathani", "Al-Mufassal", "Al-Hawamim"], "Al-Falaq en An-Nas worden al-Mu'awwidhatan genoemd, «de twee beschermers»."),
"quran_164": ("Met welk woord begint soera Al-Fatiha, na de basmala?", ["Al-hamdu", "Qul", "Iqra'", "Inna"], "«Al-hamdu lillahi rabbi l-'alamin» opent Al-Fatiha."),
"quran_165": ("Hoe heet de uitleg van de betekenis van de Koran?", ["Tafsir", "Tajwid", "Hifz", "Tawaf"], "Tafsir is de wetenschap die de betekenis van de verzen uitlegt."),
"quran_166": ("Welke soera begint niet met de basmala?", ["At-Tawba", "Al-Fatiha", "Al-Ikhlas", "An-Nasr"], "At-Tawba is de enige soera die niet met de basmala opent."),
"quran_167": ("Hoe heet iemand die de Koran hardop reciteert?", ["Een qari'", "Een muezzin", "Een imam", "Een khatib"], "De qari' is de reciteerder van de Koran."),
"quran_168": ("In welke soera staat het Troonvers?", ["Al-Baqara", "Al-Kahf", "Ya-Sin", "Al-Mulk"], "Het Troonvers is vers 255 van soera Al-Baqara."),
"quran_169": ("Wat betekent «An-Nur», de titel van soera 24?", ["Het licht", "De nacht", "De wind", "De berg"], "An-Nur betekent «het licht»."),
"quran_170": ("Welke soera heet «De Erbarmer»?", ["Ar-Rahman", "Al-Mulk", "Al-Fath", "As-Saff"], "Soera 55 heet Ar-Rahman."),
"quran_171": ("Welke soera is genoemd naar de grot?", ["Al-Kahf", "Al-Fil", "An-Naml", "Al-Baqara"], "Al-Kahf betekent «de grot»."),
"quran_172": ("Wat betekent «An-Nisa'», de titel van soera 4?", ["De vrouwen", "De mannen", "De kinderen", "De reizigers"], "An-Nisa' betekent «de vrouwen»."),
"quran_173": ("Wat betekent «Al-Ma'ida», de titel van soera 5?", ["De gedekte tafel", "De berg", "Het ijzer", "De dageraad"], "Al-Ma'ida betekent «de gedekte tafel»."),
"quran_174": ("Welke profeet geeft zijn naam aan soera 71?", ["Nuh", "Hud", "Yunus", "Ibrahim"], "Soera 71 heet Nuh."),
"quran_175": ("Hoeveel verzen heeft soera Al-Fatiha?", ["Zeven", "Drie", "Tien", "Twintig"], "Al-Fatiha heeft zeven verzen."),
"quran_176": ("Waar zegt de Koran dat hij bewaard wordt?", ["Op een Bewaarde Tafel", "In een grot", "In een kist", "Op een berg"], "«Het is een glorierijke Koran, op een Bewaarde Tafel» (85:21-22)."),
"quran_177": ("Welke soera is genoemd naar de maan?", ["Al-Qamar", "Ash-Shams", "An-Najm", "Al-Layl"], "Al-Qamar betekent «de maan»."),
"quran_178": ("Welke soera is genoemd naar de Dag der Opstanding?", ["Al-Qiyama", "Al-Fath", "Al-Hashr", "As-Saff"], "Soera 75 heet Al-Qiyama."),
"quran_179": ("Welke profeet geeft zijn naam aan soera 14?", ["Ibrahim", "Muhammad ﷺ", "Yusuf", "Hud"], "Soera 14 heet Ibrahim."),
"quran_180": ("Wat betekent «Al-Hadid», de titel van soera 57?", ["Het ijzer", "Het goud", "Het hout", "De steen"], "Al-Hadid betekent «het ijzer»."),
"virtues_101": ("Hoe zegt de Koran dat wij tegen onze ouders moeten spreken?", ["Met respectvolle woorden, zonder zelfs maar «oef» te zeggen", "Harder dan zij", "Door altijd te zwijgen", "Alleen op vrijdag"], "«Zeg niet ‘oef’ tegen hen, en spreek tot hen een edel woord» (17:23)."),
"virtues_102": ("Hoe heet een gift die je vrijwillig geeft, uit goedheid?", ["Sadaqa", "Zakat", "Tawaf", "Adhan"], "Sadaqa is vrijwillige liefdadigheid, klein of groot."),
"virtues_103": ("Wat raadt de Profeet ﷺ aan over het spreken, voor wie in Allah en de Laatste Dag gelooft?", ["Laat hij het goede zeggen of zwijgen", "Laat hij veel praten", "Laat hij nooit spreken", "Laat hij alleen met zijn familie spreken"], "«Wie in Allah en de Laatste Dag gelooft, laat hij het goede zeggen of zwijgen.»"),
"virtues_104": ("Hoe zei de Profeet ﷺ dat wij onze buur moeten behandelen?", ["Wees vrijgevig voor hem", "Vermijd hem", "Spreek nooit met hem", "Vraag hem te vertrekken"], "«Wie in Allah en de Laatste Dag gelooft, laat hij vrijgevig zijn voor zijn buur.»"),
"virtues_105": ("Met wie is Allah, volgens de Koran?", ["Met de geduldigen", "Met de rijksten", "Met de sterksten", "Met de snelsten"], "«Voorwaar, Allah is met de geduldigen» (2:153)."),
"virtues_106": ("Wat verbiedt de Koran te doen met de wees?", ["Hem hard behandelen", "Hem leren lezen", "Hem uitnodigen om te eten", "Met hem spelen"], "«Wat de wees betreft: onderdruk hem niet» (93:9)."),
"virtues_107": ("Welk soort spreken zegt de Koran ons te vermijden?", ["Leugenachtige woorden", "Zachte woorden", "Woorden van dank", "Woorden van begroeting"], "«En vermijd het leugenachtige woord» (22:30)."),
"virtues_108": ("Aan wie zegt de Koran ons, naast de naaste verwant, hun recht te geven?", ["De arme en de reiziger", "De koning en de rechter", "De koopman", "De dichter"], "«Geef de verwant zijn recht, en de arme, en de reiziger» (17:26)."),
"virtues_109": ("Wat belooft Allah aan wie Hem dankt?", ["Hem meer geven", "Hem laten reizen", "Hem beroemd maken", "Hem koning maken"], "«Als jullie dankbaar zijn, zal Ik jullie zeker meer geven» (14:7)."),
"virtues_110": ("Hoe zeg je «geduld» in het Arabisch?", ["As-sabr", "Ash-shukr", "As-sidq", "Al-haya'"], "As-sabr is standvastigheid in tegenspoed en in gehoorzaamheid."),
"faith_191": ("Hoe heet het gedenken van Allah, het herhalen van Zijn lof?", ["Dhikr", "Hajj", "Sa'y", "Tayammum"], "Dhikr is het gedenken van Allah met de tong en het hart."),
"faith_192": ("Wat is de eerste maand van het islamitische jaar?", ["Muharram", "Ramadan", "Shawwal", "Rajab"], "Het islamitische jaar (hijri) begint met de maand Muharram."),
"faith_193": ("Hoe heet het terugkeren naar Allah na een zonde?", ["Tawba", "Tawaf", "Tajwid", "Tarawih"], "Tawba is berouw: spijt hebben, ophouden en terugkeren naar Allah."),
"faith_194": ("Wie voorziet elk schepsel op aarde van levensonderhoud?", ["Allah", "Koningen", "Kooplieden", "De engelen"], "«Er is geen schepsel op aarde of zijn levensonderhoud rust op Allah» (11:6)."),
"faith_195": ("In welke stad wordt de bedevaart verricht?", ["In Mekka", "In Medina", "In Jeruzalem", "In Caïro"], "De hajj vindt plaats in Mekka en op de heilige plaatsen eromheen."),
"faith_196": ("Hoe heet iemand die de bedevaart verricht?", ["Een hajj (pelgrim)", "Een imam", "Een qari'", "Een muezzin"], "De pelgrim wordt een hajj genoemd."),
"faith_197": ("Wat weet Allah volgens de Koran, zelfs als het verborgen is?", ["Wat in de harten is", "Alleen zichtbare daden", "Alleen uitgesproken woorden", "Niets wat verborgen is"], "«Of jullie nu verbergen wat in jullie harten is of het tonen, Allah weet het» (3:29)."),
"faith_198": ("Aan wie werd het vasten voorgeschreven, volgens de Koran?", ["Aan de gelovigen, zoals aan wie vóór hen waren", "Alleen aan reizigers", "Alleen aan geleerden", "Alleen aan kinderen"], "«O jullie die geloven, het vasten is jullie voorgeschreven zoals het aan wie vóór jullie waren was voorgeschreven» (2:183)."),
"faith_199": ("Hoe heet het grote gezamenlijke gebed op vrijdag?", ["Salat al-jumu'a", "Salat al-'id", "Salat al-witr", "Salat ad-duha"], "Salat al-jumu'a brengt de moslims op vrijdagmiddag samen."),
"faith_200": ("Hoe zeg je «het vasten» in het Arabisch?", ["As-sawm", "As-salat", "Az-zakat", "Al-adhan"], "As-sawm is het vasten, de vierde zuil van de islam."),
}
